<?php
namespace App\Jobs;
use App\Models\Examination;use App\Models\User;use App\Services\Viva\VivaAuditService;use App\Services\Viva\VivaMappingApprovalService;use App\Support\Examinations\ExaminationConnectionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;
final class ApproveVivaMappingImport implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int$tries=1;public int$timeout=0;public function __construct(public int$examinationId,public int$batchId,public int$actorId){$this->onQueue((string)config('viva.queue','imports'));}public function handle(ExaminationConnectionManager$c,VivaMappingApprovalService$s,VivaAuditService$a):void{$e=Examination::findOrFail($this->examinationId);$c->configure($e);try{$b=$s->approve($this->batchId,$this->actorId);$a->record('VIVA_MAPPING_APPROVED',User::findOrFail($this->actorId),'validated','mapping_imported',summary:['approved'=>(int)$b->approved_rows,'inserted'=>(int)$b->inserted_rows,'updated'=>(int)$b->updated_rows],batchId:$b->id);}finally{$c->disconnect();}}}
